Here is a test that reproduces this (to be added to FrozenIndexTests):

```
    public void testCanMatchSortOnKeyword() throws IOException {
        createIndex("index");
        prepareIndex("index").setId("1").setSource("field", "2010-01-05T02:00", "keyword", "value1").setRefreshPolicy(IMMEDIATE).get();
        prepareIndex("index").setId("2").setSource("field", "2010-01-06T02:00", "keyword", "value2").setRefreshPolicy(IMMEDIATE).get();
        assertAcked(client().execute(FreezeIndexAction.INSTANCE, new FreezeRequest("index")).actionGet());

        {
            IndicesService indexServices = getInstanceFromNode(IndicesService.class);
            Index index = resolveIndex("index");
            IndexService indexService = indexServices.indexServiceSafe(index);
            IndexShard shard = indexService.getShard(0);
            assertTrue(indexService.getIndexSettings().isSearchThrottled());
            SearchService searchService = getInstanceFromNode(SearchService.class);
            SearchRequest searchRequest = new SearchRequest().source(SearchSourceBuilder.searchSource().sort("keyword.keyword"))
                .allowPartialSearchResults(true);
            assertTrue(
                searchService.canMatch(
                    new ShardSearchRequest(OriginalIndices.NONE, searchRequest, shard.shardId(), 0, 1, AliasFilter.EMPTY, 1f, -1, null)
                ).canMatch()
            );
        }
    }
```

